# AZ-900 crunch pack: extra cards, questions and duels for thin topics and common misses,
# checked against the skills outline of July 20, 2026. Re-running replaces the earlier crunch items.
#   python3 content/az900_crunch.py && python3 build.py
import json, random, os
P = os.path.join(os.path.dirname(__file__), '..', 'src', 'data_packs.json')
R = random.Random(2026)
CARDS, QS, DUELS = [], [], []
# question topics as the Codex and quizzes use them (section qtopics); card topics as the Deck uses them
QT = {'models': (1, 'Cloud models', 'Cloud models'), 'costm': (1, 'Cost model', 'Pricing and cost model'), 'shared': (1, 'Shared responsibility', 'Shared responsibility'),
      'benefits': (1, 'Benefits', 'Benefits of the cloud'), 'types': (1, 'Service types', 'Service types'),
      'regions': (2, 'Regions and zones', 'Regions and zones'), 'hier': (2, 'Hierarchy', 'Management hierarchy'), 'compute': (2, 'Compute', 'Compute'),
      'net': (2, 'Networking', 'Networking'), 'storage': (2, 'Storage', 'Storage'), 'ident': (2, 'Identity', 'Identity and security'), 'sec': (2, 'Security', 'Identity and security'),
      'cost': (3, 'Cost', 'Cost management'), 'gov': (3, 'Governance', 'Governance'), 'mgmt': (3, 'Management', 'Managing and deploying'), 'mon': (3, 'Monitoring', 'Monitoring')}

def C(t, front, back):
    d, _, ct = QT[t]; CARDS.append(dict(id='c%d' % (301 + len(CARDS)), d=d, topic=ct, front=front, back=back, miss=False, crunch=True))
def _q(t, **k):
    d, qt, _ = QT[t]; x = dict(id='q%d' % (301 + len(QS)), d=d, topic=qt); x.update(k); x['miss'] = False; x['crunch'] = True; QS.append(x)
def Q(t, q, right, wrong, why):
    right = [right] if isinstance(right, str) else right
    opts = right + wrong; assert len(opts) == 4 and len(set(opts)) == 4, q
    if len(right) == 2: assert 'TWO' in q, q
    R.shuffle(opts); _q(t, q=q, opts=opts, ans=sorted(opts.index(r) for r in right), why=why, kind='one' if len(right) == 1 else 'two')
def YN(t, stmts, ans, why):
    assert len(stmts) == len(ans) == 3
    _q(t, type='yn', kind='yn', q='For each statement, select Yes if it is true. Otherwise, select No.', stmts=stmts, ans=ans, why=why)
def M(t, q, pairs, why):
    rows = [a for a, _ in pairs]; ch = [b for _, b in pairs]; order = ch[:]; R.shuffle(order)
    _q(t, type='match', kind='match', q=q, rows=rows, choices=order, ans=[order.index(c) for c in ch], why=why)
def D(t, a, b, clue, ans, why):
    DUELS.append(dict(id='d%d' % (301 + len(DUELS)), d=QT[t][0], a=a, b=b, clue=clue, ans=ans, why=why, miss=False, crunch=True))

# ---------- Domain 1: cloud concepts ----------
Q('shared', "Your company moves a database from a VM to Azure SQL Database (PaaS). Which task moves from you to Microsoft?", "Patching the database server's operating system", ["Classifying the data in the database", "Managing which users can sign in", "Protecting the devices users connect from"], "In PaaS Microsoft runs the OS. Data, accounts and identities, and devices always stay with the customer.")
Q('shared', "In which service type is the customer responsible for the MOST?", "IaaS", ["PaaS", "SaaS", "It is the same for all three"], "IaaS gives you the most control and the most responsibility: OS, network controls, apps and data are yours.")
YN('shared', ["In SaaS, Microsoft is responsible for the physical datacenter.", "In IaaS, the customer is responsible for patching the virtual machine's operating system.", "In SaaS, the customer is no longer responsible for its data."], [1, 1, 0], "The physical datacenter is always Microsoft's. The OS of a VM is yours in IaaS. Data is always the customer's.")
Q('costm', "Which describes the consumption-based model?", "You pay only for the resources you use, with no upfront hardware cost", ["You pay one fixed price per year for unlimited capacity", "You buy servers upfront and depreciate them over time", "You pay for capacity reserved even when it is not used"], "Consumption-based means pay for what you use, when you use it. It is an OpEx model with no upfront CapEx.")
Q('costm', "Which TWO are examples of operational expenditure (OpEx)?", ["Paying monthly for Azure virtual machines", "Paying per GB stored in Azure Storage"], ["Buying servers for a new datacenter", "Building a server room"], "OpEx is spending on services as you use them. Buying hardware or buildings is CapEx.")
Q('models', "Which describes serverless computing?", "The cloud provider manages the servers and you are billed only when your code runs", ["There are no servers involved at all", "You manage the OS but not the hardware", "You must reserve servers a year in advance"], "Serverless still runs on servers, but the provider manages them and scales automatically. You pay only for execution. Azure Functions is the classic example.")
Q('models', "A government agency must run workloads only on hardware that it owns and that no other organization uses. Which cloud model fits?", "Private cloud", ["Public cloud", "Hybrid cloud", "Multicloud"], "A private cloud is used by one organization only. The public cloud shares hardware between many customers.")
M('models', "Match each scenario to the cloud model.", [("Run everything on Microsoft-owned shared hardware", "Public cloud"), ("Keep all servers in your own datacenter, used only by you", "Private cloud"), ("Keep sensitive data on premises and burst to Azure for peaks", "Hybrid cloud")], "Public = provider's shared hardware. Private = one organization only. Hybrid = both, connected.")
Q('benefits', "An online store adds VMs automatically during a holiday sale and removes them afterwards. Which benefit is this?", "Elasticity (scalability)", ["Predictability", "Governance", "Manageability"], "Adding and removing resources automatically as demand changes is elasticity, a form of scalability.")
Q('benefits', "Which benefit lets you forecast your monthly cloud bill and expected performance?", "Predictability", ["Reliability", "High availability", "Security"], "Predictability covers both cost and performance. Tools like the pricing calculator and autoscaling support it.")
Q('types', "A team wants to deploy its web app without managing servers, operating systems or patching. Which service type fits?", "PaaS", ["IaaS", "SaaS", "On-premises"], "PaaS gives a managed platform for your own code. IaaS would leave the OS to you. SaaS is a finished app, not your code.")
D('costm', "CapEx", "OpEx", "Pay monthly for the VMs you used.", 1, "Paying for services as you use them is OpEx. CapEx is upfront spending on physical assets.")
D('models', "Private cloud", "Hybrid cloud", "Some workloads on premises, some in Azure, connected.", 1, "Hybrid combines private and public. Private is one organization's own infrastructure only.")
C('costm', "Consumption-based model in one line?", "Pay for what you use, when you use it. No upfront hardware (no CapEx). Scales up and down with demand.")
C('models', "What is serverless?", "The provider manages the servers, scaling and OS. You deploy code or a workload and pay only while it runs. Example: **Azure Functions**.")

# ---------- Domain 2: architecture and services ----------
Q('regions', "Which statement about Azure region pairs is true?", "Planned platform updates are rolled out to one region of a pair at a time", ["Both regions of a pair are always in different geographies", "Region pairs replace the need for availability zones", "Every resource is automatically copied to the paired region"], "Updates go to one region of a pair at a time, and one region of each pair is prioritized for recovery in a wide outage. Pairs stay in the same geography (Brazil South is the exception). Replication is not automatic for every resource.")
Q('regions', "A US federal agency needs a cloud physically and logically isolated for government use. What should it use?", "Azure Government, a sovereign region", ["A region pair", "An availability zone", "A management group"], "Sovereign regions are separate instances of Azure for compliance or legal reasons, such as Azure Government (US) and Azure operated by 21Vianet (China).")
Q('regions', "A VM must keep running if a whole datacenter in the region fails. What should you use?", "Availability zones", ["A resource group", "A single VM with a premium disk", "Azure Advisor"], "Availability zones are physically separate datacenters in a region with their own power, cooling and network.")
YN('regions', ["Every Azure region supports availability zones.", "An availability zone is made up of one or more datacenters.", "A zone-enabled region has at least three availability zones."], [0, 1, 1], "Not every region has zones. Each zone is one or more datacenters with independent power, cooling and networking, and zone-enabled regions have at least three.")
Q('hier', "You apply an Azure Policy to a management group. Where does it take effect?", "On every subscription, resource group and resource below that management group", ["Only on the management group itself", "Only on new subscriptions", "Only on resources that are tagged"], "Policy, access (RBAC) and locks are inherited down the hierarchy: management group, subscription, resource group, resource.")
Q('hier', "Which statement about resource groups is true?", "Deleting a resource group deletes every resource in it", ["A resource can belong to several resource groups", "Resource groups can be nested", "A resource group can span several subscriptions"], "A resource is in exactly one resource group, groups cannot be nested, and deleting the group deletes everything inside.")
Q('hier', "A company needs separate billing for each department. What should it create for each department?", "A subscription", ["A resource group", "A resource tag only", "An availability zone"], "A subscription is a billing boundary and an access boundary. Departments often get their own subscription, grouped under management groups.")
M('hier', "Match each Azure scope to its description.", [("Groups subscriptions so policy and access apply to all of them", "Management group"), ("Billing and access boundary", "Subscription"), ("Logical container for resources that share a lifecycle", "Resource group"), ("A single VM, storage account or database", "Resource")], "Management groups hold subscriptions, subscriptions hold resource groups, resource groups hold resources.")
Q('compute', "Which TWO resources are created along with an Azure virtual machine?", ["A network interface", "A disk for the operating system"], ["An Azure Function", "A management group"], "A VM needs compute size, storage disks and networking: a virtual network, a network interface and optionally a public IP address.")
Q('compute', "You need to run a single container quickly with no orchestration or VMs to manage. Which service fits?", "Azure Container Instances", ["Azure Kubernetes Service", "Azure Virtual Desktop", "Virtual Machine Scale Sets"], "Container Instances is the simplest way to run a container. AKS orchestrates many containers.")
Q('compute', "Which provides Windows desktops and apps hosted in Azure that users reach from any device?", "Azure Virtual Desktop", ["Azure Bastion", "Azure App Service", "Azure Container Instances"], "Azure Virtual Desktop is desktop and app virtualization in the cloud, with multi-session Windows.")
D('compute', "Virtual Machine Scale Sets", "Availability sets", "Spread VMs across fault and update domains so a rack failure or reboot does not take them all down.", 1, "Availability sets protect against hardware failure and planned updates. Scale sets add and remove identical VMs for load.")
Q('net', "A web app should be reachable only from your virtual network, using a private IP address. What should you use?", "A private endpoint", ["A public endpoint", "Azure DNS", "A VPN gateway"], "A private endpoint gives a service a private IP address in your virtual network (through Private Link), so traffic stays off the public internet.")
Q('net', "Two virtual networks in different regions must talk to each other over the Microsoft backbone. What should you configure?", "Virtual network peering", ["A public endpoint", "ExpressRoute", "Azure DNS"], "Peering connects virtual networks, including across regions (global peering), over Microsoft's backbone.")
Q('net', "You need a private, dedicated connection from your datacenter to Azure that does not cross the public internet. What should you use?", "ExpressRoute", ["VPN Gateway", "Virtual network peering", "Azure DNS"], "ExpressRoute is a private connection through a connectivity provider. A VPN gateway sends encrypted traffic over the public internet.")
D('net', "Public endpoint", "Private endpoint", "Gets a private IP address from your virtual network.", 1, "Private endpoints use a private IP in your VNet. Public endpoints use a public IP reachable from the internet.")
Q('storage', "Data must be kept for at least 180 days and is almost never read. Retrieval can take hours. Which access tier costs least?", "Archive", ["Hot", "Cool", "Cold"], "Archive has the lowest storage cost but is offline: data must be rehydrated, which takes hours. Minimum retention 180 days.")
M('storage', "Match each access tier to its minimum recommended retention.", [("Cool", "30 days"), ("Cold", "90 days"), ("Archive", "180 days")], "Cool 30, cold 90, archive 180. Hot has no minimum. Moving data out early incurs an early deletion charge.")
Q('storage', "Which redundancy option keeps three copies in three availability zones of the primary region only?", "Zone-redundant storage (ZRS)", ["Locally redundant storage (LRS)", "Geo-redundant storage (GRS)", "Geo-zone-redundant storage (GZRS)"], "ZRS spreads three copies across zones in one region. LRS keeps three copies in one datacenter. GRS and GZRS add a secondary region.")
Q('storage', "You need geo-redundancy AND the ability to read data from the secondary region at any time. Which option?", "RA-GRS", ["GRS", "ZRS", "LRS"], "The RA (read-access) versions, RA-GRS and RA-GZRS, let you read from the secondary region without a failover.")
Q('storage', "Which storage account type is recommended for most scenarios and supports blobs, files, queues and tables?", "Standard general-purpose v2", ["Premium block blobs", "Premium file shares", "Premium page blobs"], "Standard general-purpose v2 covers most scenarios. Premium accounts are for low-latency workloads of one type.")
Q('storage', "You must copy files to Azure Blob Storage from a command line script. Which tool fits?", "AzCopy", ["Azure Storage Explorer", "Azure File Sync", "Azure Data Box"], "AzCopy is a command-line tool. Storage Explorer is a graphical app. File Sync keeps on-premises file servers in sync with Azure Files.")
Q('storage', "Branch offices want their Windows file servers to cache Azure file shares locally. Which service?", "Azure File Sync", ["AzCopy", "Azure Migrate", "Azure Storage Explorer"], "Azure File Sync turns a Windows Server into a local cache of an Azure file share.")
Q('storage', "You must move 60 TB of data to Azure but the internet link is slow. What should you use?", "Azure Data Box", ["AzCopy", "Azure Migrate", "Azure File Sync"], "Data Box is a physical device (up to 80 TB) shipped to you, filled, and returned to Microsoft for upload.")
D('storage', "Azure Migrate", "Azure Data Box", "One hub to discover, assess and migrate on-premises servers, databases and web apps.", 0, "Azure Migrate is the migration hub. Data Box moves large amounts of data offline on a physical device.")
D('storage', "Azure Storage Explorer", "AzCopy", "Graphical app to manage storage accounts from Windows, macOS or Linux.", 0, "Storage Explorer is the GUI. AzCopy is the command-line tool.")
C('storage', "Storage tiers and minimum retention?", "**Hot** (frequent access, no minimum), **Cool** 30 days, **Cold** 90 days, **Archive** 180 days and offline (rehydrate takes hours). Cooler = cheaper to store, dearer to read.")
C('storage', "Redundancy options in one breath?", "**LRS** 3 copies in one datacenter. **ZRS** 3 zones in one region. **GRS** LRS + copy to a secondary region. **GZRS** ZRS + secondary region. **RA-** = you can read the secondary.")
C('storage', "AzCopy vs Storage Explorer vs File Sync?", "**AzCopy:** command line copy. **Storage Explorer:** graphical app. **File Sync:** Windows file server caches an Azure file share.")
C('compute', "Resources a VM needs?", "Size (CPU and memory), storage disks (OS disk, optional data disks), and networking: a virtual network, a network interface, and optionally a public IP address.")
C('net', "Public vs private endpoint?", "**Public endpoint:** public IP, reachable from the internet. **Private endpoint:** private IP from your virtual network through Private Link; traffic stays on the Microsoft network.")
C('regions', "What are sovereign regions?", "Separate instances of Azure isolated for compliance or legal reasons: **Azure Government** (US agencies) and **Azure operated by 21Vianet** (China).")
Q('ident', "A legacy app needs domain join, Group Policy and Kerberos, but you do not want to run domain controllers in Azure. What should you use?", "Microsoft Entra Domain Services", ["Microsoft Entra ID alone", "Azure Policy", "Microsoft Entra B2B"], "Entra Domain Services provides managed domain services (domain join, Group Policy, LDAP, Kerberos and NTLM) without you deploying domain controllers.")
Q('ident', "Partner company staff must sign in to your app using their own work accounts. Which feature?", "Microsoft Entra External ID (B2B collaboration)", ["Conditional Access", "Microsoft Entra Domain Services", "Azure RBAC"], "External identities let people outside your organization use their own identities to reach your apps.")
Q('ident', "Users sign in once and then reach Microsoft 365, the Azure portal and other apps without signing in again. What is this?", "Single sign-on (SSO)", ["Multifactor authentication", "Passwordless authentication", "Conditional Access"], "SSO means one sign-in, one set of credentials, many apps.")
Q('ident', "Which TWO are passwordless authentication methods in Azure?", ["Windows Hello for Business", "Microsoft Authenticator app"], ["A password plus an SMS code", "A security question"], "Passwordless methods include Windows Hello for Business, the Microsoft Authenticator app and FIDO2 security keys (passkeys).")
D('ident', "Microsoft Entra ID", "Microsoft Entra Domain Services", "Managed domain join, Group Policy and Kerberos for legacy apps.", 1, "Entra Domain Services adds traditional domain features without domain controllers. Entra ID is the cloud identity service.")
D('sec', "Azure RBAC", "Conditional Access", "Require MFA when a user signs in from an unknown location.", 1, "Conditional Access decides HOW you may sign in based on signals. RBAC decides WHAT you may do once signed in.")
Q('sec', "A user needs to restart VMs in one resource group but nothing else. Which feature grants exactly that?", "Azure role-based access control (RBAC) at the resource group scope", ["A resource lock", "Azure Policy", "Microsoft Defender for Cloud"], "RBAC assigns a role at a scope. Least privilege means the narrowest role at the narrowest scope.")

# ---------- Domain 3: management and governance ----------
Q('gov', "Developers must be prevented from creating resources outside the East US region. What should you use?", "Azure Policy", ["A resource lock", "Azure RBAC", "Tags"], "Azure Policy enforces rules about how resources are configured, such as allowed regions, and can deny non-compliant deployments.")
Q('gov', "A production database must not be deleted by accident, even by an Owner. What should you apply?", "A Delete (CanNotDelete) resource lock", ["Azure Policy", "A ReadOnly tag", "An RBAC Reader role"], "Locks apply to everyone, including Owners. A Delete lock allows changes but blocks deletion. ReadOnly blocks both.")
YN('gov', ["A resource lock applies even to users with the Owner role.", "To delete a resource with a Delete lock, you must first remove the lock.", "A ReadOnly lock still allows the resource to be deleted."], [1, 1, 0], "Locks override RBAC permissions for everyone. Remove the lock first. ReadOnly blocks changes AND deletion.")
M('gov', "Match each requirement to the right tool.", [("Only allow VM sizes from an approved list", "Azure Policy"), ("Stop anyone deleting a storage account", "Resource lock"), ("Give the help desk permission to restart VMs", "Azure RBAC"), ("Group costs by department on the bill", "Tags")], "Policy controls HOW resources are configured. Locks stop change or deletion. RBAC controls WHO can do what. Tags add metadata for cost and organization.")
Q('gov', "What is an Azure Policy initiative?", "A group of related policy definitions assigned together", ["A lock applied to a whole subscription", "A role with custom permissions", "A tag that is inherited by every resource"], "Initiatives bundle policies toward one goal, such as a compliance standard, so you assign and track them as one.")
Q('gov', "Which service gives a unified view to discover, classify and govern data across on-premises, multicloud and SaaS?", "Microsoft Purview", ["Azure Policy", "Azure Advisor", "Microsoft Defender for Cloud"], "Microsoft Purview is a family of data governance, risk and compliance solutions with one view of your data estate.")
D('gov', "Azure Policy", "Resource lock", "Block resources from being created in an unapproved region.", 0, "Policy controls how resources are configured and can deny deployments. Locks only stop changes or deletion of existing resources.")
D('gov', "Azure Policy", "Azure RBAC", "Decides who is allowed to restart a VM.", 1, "RBAC controls who can do what. Policy controls what resources may look like, whoever deploys them.")
C('gov', "Policy vs lock vs RBAC?", "**Policy:** what resources may look like (regions, sizes, tags). **Lock:** stop deletion (Delete) or any change (ReadOnly), even for Owners. **RBAC:** who can do what, at which scope.")
C('gov', "Delete lock vs ReadOnly lock?", "**Delete (CanNotDelete):** can read and modify, cannot delete. **ReadOnly:** can read only, no changes and no deletion. Both apply to every user and are inherited downward.")
Q('cost', "Which TWO factors affect the cost of Azure resources?", ["The Azure region the resource is deployed in", "Outbound data transfer (egress) between regions"], ["The number of tags on the resource", "The number of resource groups in the subscription"], "Cost depends on resource type, consumption, maintenance, geography (region), network traffic (egress), subscription type and Marketplace items. Tags and resource groups are free.")
Q('cost', "Before deploying anything, you want to estimate the monthly cost of three VMs and a SQL database. Which tool?", "Azure pricing calculator", ["Microsoft Cost Management", "Azure Advisor", "Azure Service Health"], "The pricing calculator estimates costs before you deploy. Cost Management analyzes and controls what you are already spending.")
Q('cost', "You want an email when a subscription's spending reaches 80% of a monthly amount. What should you create?", "A budget in Microsoft Cost Management", ["A resource lock", "An Azure Policy", "A Service Health alert"], "Budgets in Cost Management trigger alerts at thresholds you set. Budgets alert; they do not stop resources by themselves.")
Q('cost', "Which TWO are uses of resource tags?", ["Grouping costs by department in cost reports", "Identifying which resources belong to a project"], ["Encrypting data at rest", "Preventing a resource from being deleted"], "Tags are name/value pairs for organization, cost reporting, automation and governance. Locks prevent deletion.")
D('cost', "Pricing calculator", "Microsoft Cost Management", "See what you spent last month, broken down by resource group.", 1, "Cost Management analyzes actual spend and sets budgets. The pricing calculator estimates before you deploy.")
D('cost', "Tags", "Management groups", "Add a CostCenter=Finance label to individual resources.", 0, "Tags label resources with metadata. Management groups organize subscriptions for governance.")
C('cost', "Factors that affect Azure cost?", "Resource type and size, consumption, maintenance (leftover resources), **geography** (region), **network traffic** (egress and between regions), subscription type, Azure Marketplace items. Inbound data is free.")
C('cost', "Pricing calculator vs Cost Management?", "**Pricing calculator:** estimate before you deploy. **Cost Management:** analyze actual spend, set **budgets** and alerts, get recommendations.")
Q('mgmt', "You need a browser-based shell with Azure CLI and Azure PowerShell already installed and signed in. What should you use?", "Azure Cloud Shell", ["Azure Arc", "Azure Advisor", "ARM templates"], "Cloud Shell runs in the browser (Bash or PowerShell) with the tools already installed and authenticated.")
Q('mgmt', "You must manage on-premises servers and servers in AWS from the Azure portal, applying Azure Policy to them. What should you use?", "Azure Arc", ["Azure Cloud Shell", "Azure Migrate", "ExpressRoute"], "Azure Arc projects non-Azure resources (servers, Kubernetes, data services) into Azure Resource Manager so you can manage and govern them in Azure.")
Q('mgmt', "What is infrastructure as code (IaC)?", "Defining infrastructure in files so it can be deployed the same way every time", ["Writing app code that runs on infrastructure", "Buying hardware through a portal", "Monitoring infrastructure with code-based alerts"], "IaC describes resources in code (ARM templates, Bicep) so deployments are repeatable and version-controlled.")
Q('mgmt', "Which TWO are benefits of ARM templates?", ["They are declarative: you say what you want, not how to build it", "Deploying the same template again gives the same result"], ["They replace the need for Azure RBAC", "They only work from the Azure portal"], "ARM templates are declarative JSON, repeatable (idempotent), orchestrated and modular. Bicep is a simpler language for the same deployments.")
YN('mgmt', ["Every request to manage Azure resources, from the portal, CLI or PowerShell, goes through Azure Resource Manager.", "Bicep is a language for declaring Azure resources that is simpler than ARM template JSON.", "Azure Cloud Shell requires installing the Azure CLI on your own computer."], [1, 1, 0], "ARM is the single management layer for all tools. Bicep compiles to ARM templates. Cloud Shell runs in the browser with the tools preinstalled.")
D('mgmt', "Azure Arc", "Azure Migrate", "Manage and apply policy to servers that stay in another cloud.", 0, "Arc manages resources where they are. Migrate moves them into Azure.")
C('mgmt', "Azure Arc in one line?", "Extends Azure management (portal, Policy, RBAC, Monitor) to servers, Kubernetes and data services outside Azure: on-premises or other clouds.")
C('mgmt', "ARM and ARM templates?", "**Azure Resource Manager:** the deployment and management layer every tool goes through. **ARM templates:** declarative JSON (or Bicep) infrastructure as code. Repeatable, orchestrated, modular.")
Q('mon', "Which service gives personalized recommendations for reliability, security, performance, operational excellence and cost?", "Azure Advisor", ["Azure Service Health", "Azure Monitor alerts", "Microsoft Purview"], "Advisor analyzes your resources and recommends improvements in those five categories.")
Q('mon', "Developers need to see request rates, response times and failure rates of their web app. Which feature?", "Application Insights", ["Azure Advisor", "Azure Service Health", "Microsoft Cost Management"], "Application Insights, part of Azure Monitor, monitors the performance and usage of web applications.")
Q('mon', "Where do you write queries (KQL) against logs collected by Azure Monitor?", "Log Analytics", ["Azure Advisor", "Application Insights availability tests", "Azure Service Health"], "Log Analytics is the Azure Monitor tool for writing and running log queries.")
M('mon', "Match each need to the right tool.", [("Is there an Azure outage in a region I use?", "Azure Service Health"), ("How can I cut costs on idle VMs?", "Azure Advisor"), ("Email me when CPU stays above 90%", "Azure Monitor alerts"), ("Why is my web app slow for users?", "Application Insights")], "Service Health = Azure's health for you. Advisor = recommendations. Monitor alerts = act on your metrics and logs. Application Insights = app performance.")
YN('mon', ["Azure status shows the health of Azure services globally.", "Resource Health shows the health of your individual resources.", "Azure Advisor can automatically fix every recommendation it makes."], [1, 1, 0], "Service Health has three views: Azure status (global), Service Health (your services and regions) and Resource Health (your resources). Advisor recommends; you act.")
D('mon', "Azure Monitor alerts", "Azure Advisor", "Notify me when a VM's CPU stays above 90% for 10 minutes.", 0, "Alerts react to your metrics and logs. Advisor gives best-practice recommendations.")
C('mon', "Service Health's three views?", "**Azure status:** global health of all Azure services. **Service Health:** issues and maintenance affecting the services and regions you use. **Resource Health:** health of your individual resources.")
C('mon', "Azure Monitor parts?", "**Log Analytics:** query logs with KQL. **Alerts:** notify or act when metrics or logs cross a threshold. **Application Insights:** web app performance and usage.")

# ---------- self-checks, then write ----------
data = json.load(open(P, encoding='utf-8')); pk = data['packs']['az900']
for k, new in (('cards', CARDS), ('questions', QS), ('duels', DUELS)):
    base = [x for x in pk[k] if not x.get('crunch')]
    ids = {x['id'] for x in base}; assert not ids & {x['id'] for x in new}, k
    pk[k] = base + new
qt = {t for s in pk['sections'] for t in s['qtopics']}; ct = {t for s in pk['sections'] for t in s['topics']}
assert all(q['topic'] in qt for q in QS) and all(c['topic'] in ct for c in CARDS)
for q in QS:
    if q['kind'] in ('one', 'two'): assert all(0 <= a < 4 for a in q['ans'])
for d in DUELS: assert d['ans'] in (0, 1) and d['a'] != d['b']
json.dump(data, open(P, 'w', encoding='utf-8'), ensure_ascii=False)
print('az900 crunch:', len(CARDS), 'cards,', len(QS), 'questions,', len(DUELS), 'duels; totals', {k: len(pk[k]) for k in ('cards', 'questions', 'duels')})
